<span class="line"><span class="token keyword">bool</span> <span class="token function">set_active_soft_key_mask</span><span class="token punctuation">(</span>VirtualTerminalClient<span class="token double-colon punctuation">::</span>MaskType maskType<span class="token punctuation">,</span> std<span class="token double-colon punctuation">::</span><span class="token keyword">uint16_t</span> maskId<span class="token punctuation">,</span> std<span class="token double-colon punctuation">::</span><span class="token keyword">uint16_t</span> softKeyMaskId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
